mapper.select:
SELECT

FROM audit_log ol
LEFT JOIN users u ON ol.user_id = u.id AND u.is_del = 0
LEFT JOIN employee e ON u.employee_id = e.id AND e.delflag = 0
LEFT JOIN department d ON e.department_id = d.id AND d.delflag = 0


        AND ol.user_name LIKE CONCAT('%', #{userName}, '%')


        AND ol.module = #{module}


        AND ol.operation = #{operation}


        AND ol.operation_time >= #{startTime}


        AND ol.operation_time <= #{endTime}


        AND ol.ip_address = #{ipAddress}


        AND ol.target_type = #{targetType}


ORDER BY ol.operation_time DESC

SELECT

FROM audit_log
WHERE user_id = #{userId}
ORDER BY operation_time DESC
LIMIT #{limit}

SELECT operation, COUNT(*) as count FROM audit_log
AND operation_time >= #{startTime}
AND operation_time <= #{endTime}
GROUP BY operation ORDER BY count DESC

SELECT module, COUNT(*) as count FROM audit_log
AND operation_time >= #{startTime}
AND operation_time <= #{endTime}
GROUP BY module ORDER BY count DESC

SELECT 
    ip_address,
    COUNT(*) as access_count
FROM audit_log


        AND operation_time >= #{startTime}


        AND operation_time <= #{endTime}


GROUP BY ip_address
ORDER BY access_count DESC
LIMIT #{limit}

SELECT ol.user_name, u.nickname, COUNT(*) as operation_count FROM audit_log ol LEFT JOIN users u ON ol.user_id = u.id AND u.is_del = 0
AND ol.operation_time >= #{startTime}
AND ol.operation_time <= #{endTime}
GROUP BY ol.user_name, u.nickname ORDER BY operation_count DESC LIMIT #{limit}

SELECT DATE_FORMAT(operation_time, #{dateFormat}) as date_key, COUNT(*) as operation_count FROM audit_log
AND operation_time >= #{startTime}
AND operation_time <= #{endTime}
GROUP BY DATE_FORMAT(operation_time, #{dateFormat}) ORDER BY date_key ASC

SELECT COUNT(*)
FROM audit_log


        AND operation_time >= #{startTime}


        AND operation_time <= #{endTime}


        AND module = #{module}
